import {useCallback,useEffect,useMemo,useRef,useState} from 'react';
import type {CSSProperties,ReactNode} from 'react';
import {Badge,Button,Divider,Field,FluentProvider,Input,Menu,MenuItem,MenuList,MenuPopover,MenuTrigger,MessageBar,MessageBarBody,MessageBarTitle,ProgressBar,Select,Slider,Spinner,Switch,Tab,TabList,Textarea,Toast,ToastBody,Toaster,ToastTitle,Tooltip,useId,useToastController} from '@fluentui/react-components';
import {Add20Regular,ArrowClockwise20Regular,ArrowDown20Regular,ArrowDownload20Regular,ArrowLeft20Regular,ArrowRight20Regular,ArrowSort20Regular,ArrowUp20Regular,Checkmark16Regular,CheckmarkCircle20Regular,ChevronDoubleLeft20Regular,ChevronDoubleRight20Regular,ChevronRight16Regular,Clock20Regular,Delete20Regular,Desktop20Regular,DocumentText20Regular,DoorArrowRight20Regular,Edit20Regular,ErrorCircle20Regular,Eye20Regular,Globe20Regular,GridDots20Regular,Info20Regular,LockClosed20Regular,MoreHorizontal20Regular,Navigation20Regular,Person20Regular,PersonAccounts20Regular,PlugConnected20Regular,PlugDisconnected20Regular,Power20Regular,Search20Regular,Settings20Regular,ShieldCheckmark20Regular,SignOut20Regular,WeatherMoon20Regular,WeatherSunny20Regular,Wifi120Regular} from '@fluentui/react-icons';
import {DndContext,PointerSensor,KeyboardSensor,closestCenter,useSensor,useSensors} from '@dnd-kit/core';
import type {DragEndEvent} from '@dnd-kit/core';
import {SortableContext,arrayMove,sortableKeyboardCoordinates,useSortable,verticalListSortingStrategy} from '@dnd-kit/sortable';
import {CSS} from '@dnd-kit/utilities';
import {api,ApiError,defaultConnection,defaultPower,isDesktop} from './api';
import type {Account,AccountInput,ActionResult,AppInfo,Connection,Countdown,Diagnostics,Power,Profile,Reconnect,Service,Session,Snapshot,Status,UpdateInfo} from './api';
import {ConfirmDialog,EmptyState,IconButton,Modal,Panel,PasswordInput,SearchSelect,SettingRow,StatusBadge,ToggleRow} from './components';
import {darkTheme,lightTheme,withTextSize} from './theme';

type Page='connection'|'accounts'|'reconnect'|'power'|'settings';
type Theme='light'|'dark'|'system';
interface UiPrefs {collapsed:boolean;width:number;theme:Theme;textSize:number}
interface DesktopPrefs {autostart:boolean;close_to_tray:boolean;minimize_to_tray:boolean;close_notice_seen?:boolean}
const navigation:{id:Page;label:string;icon:ReactNode;subtitle:string}[]=[{id:'connection',label:'网络连接',icon:<Wifi120Regular/>,subtitle:'让每一次连接，都更省心。'},{id:'accounts',label:'账号管理',icon:<PersonAccounts20Regular/>,subtitle:'管理你的校园网账号与认证顺序。'},{id:'reconnect',label:'自动重连',icon:<ArrowClockwise20Regular/>,subtitle:'网络偶尔掉线，连接不用重来。'},{id:'power',label:'电源计划',icon:<Power20Regular/>,subtitle:'让设备跟上你的作息。'},{id:'settings',label:'设置与关于',icon:<Settings20Regular/>,subtitle:'按照你的习惯，设置这台设备。'}];
const weekdays=[['mon','周一'],['tue','周二'],['wed','周三'],['thu','周四'],['fri','周五'],['sat','周六'],['sun','周日']];
const emptyAccount=(service:string):AccountInput=>({label:'',username:'',password:'',service,enabled:true,note:''});
const errorMessage=(error:unknown)=>error instanceof Error?error.message:String(error);
const clock=(seconds?:number)=>seconds?new Date(seconds*1000).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'尚未检测';
function loadUi():UiPrefs{try{const saved=JSON.parse(localStorage.getItem('campusauth-ui')||'{}');return{collapsed:false,width:228,theme:'system',...saved,textSize:Math.max(13,Math.min(20,Number(saved.textSize)||15))}}catch{return{collapsed:false,width:228,theme:'system',textSize:15}}}

export function App(){
  const [prefs,setPrefs]=useState<UiPrefs>(loadUi);
  const [systemDark,setSystemDark]=useState(matchMedia('(prefers-color-scheme:dark)').matches);
  useEffect(()=>{const listener=(event:MediaQueryListEvent)=>setSystemDark(event.matches);const media=matchMedia('(prefers-color-scheme:dark)');media.addEventListener('change',listener);return()=>media.removeEventListener('change',listener)},[]);
  useEffect(()=>{localStorage.setItem('campusauth-ui',JSON.stringify(prefs))},[prefs]);
  const dark=prefs.theme==='dark'||(prefs.theme==='system'&&systemDark);
  const theme=useMemo(()=>withTextSize(dark?darkTheme:lightTheme,prefs.textSize),[dark,prefs.textSize]);
  useEffect(()=>{document.documentElement.style.fontSize=`${prefs.textSize}px`},[prefs.textSize]);
  useEffect(()=>{document.documentElement.style.colorScheme=dark?'dark':'light';document.documentElement.style.backgroundColor=dark?'#121b24':'#f5f7fa';document.body.style.backgroundColor=dark?'#121b24':'#f5f7fa'},[dark]);
  return <FluentProvider theme={theme} className={'fluent-app '+(dark?'theme-dark':'theme-light')+(prefs.textSize>=18?' large-text':'')}><CampusApp prefs={prefs} setPrefs={setPrefs} dark={dark}/></FluentProvider>;
}

function CampusApp({prefs,setPrefs,dark}:{prefs:UiPrefs;setPrefs:React.Dispatch<React.SetStateAction<UiPrefs>>;dark:boolean}){
  const [page,setPage]=useState<Page>('connection');
  const [snapshot,setSnapshot]=useState<Snapshot|null>(null);
  const [status,setStatus]=useState<Status|null>(null);
  const [power,setPower]=useState<Power>(defaultPower);
  const [countdown,setCountdown]=useState<Countdown>({ok:true,active:false});
  const [profiles,setProfiles]=useState<Profile[]>([]);
  const [services,setServices]=useState<Service[]>([]);
  const [info,setInfo]=useState<AppInfo|null>(null);
  const [desktopPrefs,setDesktopPrefs]=useState<DesktopPrefs>({autostart:false,close_to_tray:true,minimize_to_tray:false});
  const [session,setSession]=useState<Session|null>(isDesktop?{authenticated:true,setup_required:false,username:'管理员'}:null);
  const [initializing,setInitializing]=useState(true);
  const [initialError,setInitialError]=useState('');
  const [busy,setBusy]=useState<string|null>(null);
  const [refreshing,setRefreshing]=useState(false);
  const [accountId,setAccountId]=useState('');
  const [accountEditor,setAccountEditor]=useState<AccountInput|null>(null);
  const [accountError,setAccountError]=useState('');
  const [confirmation,setConfirmation]=useState<{title:string;description:string;action:string;danger?:boolean;run:()=>Promise<void>}|null>(null);
  const [details,setDetails]=useState<{title:string;description:string;text:string;elevate?:'install'|'remove'}|null>(null);
  const [onboarding,setOnboarding]=useState(false);
  const [mobileNav,setMobileNav]=useState(false);
  const [dragging,setDragging]=useState(false);
  const [maximized,setMaximized]=useState(false);
  const [update,setUpdate]=useState<UpdateInfo|null>(null);
  const [diagnosticsPreview,setDiagnosticsPreview]=useState(false);
  const [lastFailure,setLastFailure]=useState('');
  const toasterId=useId('campus-notices');
  const {dispatchToast}=useToastController(toasterId);
  const busyRef=useRef<string|null>(null);
  const mounted=useRef(true);
  const notify=useCallback((title:string,intent:'success'|'error'|'info'='success',body?:string)=>dispatchToast(<Toast><ToastTitle>{title}</ToastTitle>{body&&<ToastBody>{body}</ToastBody>}</Toast>,{intent,timeout:intent==='error'?7000:3500}),[dispatchToast]);
  useEffect(()=>{mounted.current=true;return()=>{mounted.current=false}},[]);
  const refreshSnapshot=useCallback(async()=>{const next=await api<Snapshot>('snapshot');if(mounted.current)setSnapshot(next);return next},[]);
  const refreshStatus=useCallback(async()=>{if(refreshing)return;setRefreshing(true);try{const next=await api<Status>('status');if(mounted.current)setStatus(next)}catch(error){if(error instanceof ApiError&&error.status===401)setSession(null);else notify('网络检测未完成','error',errorMessage(error))}finally{if(mounted.current)setRefreshing(false)}},[refreshing,notify]);
  const loadApp=useCallback(async()=>{
    setInitializing(true);setInitialError('');
    try{
      if(!isDesktop){const current=await api<Session>('session');setSession(current);if(!current.authenticated){setInitializing(false);return}}
      const next=await refreshSnapshot();
      const loaded=await Promise.allSettled([api<Profile[]>('profiles'),api<Power>('power'),api<AppInfo>('app/info'),...(isDesktop?[api<DesktopPrefs>('app/preferences')]:[])]);
      if(loaded[0].status==='fulfilled')setProfiles(loaded[0].value as Profile[]);
      if(loaded[1].status==='fulfilled')setPower(loaded[1].value as Power);
      if(loaded[2].status==='fulfilled')setInfo(loaded[2].value as AppInfo);
      if(loaded[3]?.status==='fulfilled')setDesktopPrefs(loaded[3].value as DesktopPrefs);
      if(!next.accounts.length&&!localStorage.getItem('campusauth-onboarded'))setOnboarding(true);
      setInitializing(false);
      void api<Status>('status').then(setStatus).catch(()=>{});
    }catch(error){if(error instanceof ApiError&&error.status===401)setSession(null);else setInitialError(errorMessage(error));setInitializing(false)}
  },[refreshSnapshot]);
  useEffect(()=>{void loadApp()},[loadApp]);
  useEffect(()=>{if(!isDesktop)return;let cleanup:(()=>void)[]=[];let canceled=false;void import('@tauri-apps/api/event').then(async({listen})=>{
    const refresh=()=>{void refreshSnapshot().catch(()=>{});void api<Status>('status').then(setStatus).catch(()=>{})};
    const changes=await listen('campus-auth:changed',refresh);const reconnected=await listen('campus-auth:reconnect',refresh);const navigate=await listen<{page:Page}>('campus-auth:navigate',event=>{if(navigation.some(item=>item.id===event.payload.page))setPage(event.payload.page)});
    if(canceled){changes();reconnected();navigate()}else cleanup=[changes,reconnected,navigate];
  });return()=>{canceled=true;cleanup.forEach(stop=>stop())}},[refreshSnapshot]);
  useEffect(()=>{if(!isDesktop)return;const update=()=>void api<{maximized:boolean}>('app/window/is-maximized').then(result=>setMaximized(result.maximized)).catch(()=>{});update();window.addEventListener('resize',update);return()=>window.removeEventListener('resize',update)},[]);
  useEffect(()=>{if(!snapshot||!session?.authenticated)return;const timer=setInterval(()=>{if(!busyRef.current){void api<Status>('status').then(setStatus).catch(()=>{});void refreshSnapshot().catch(()=>{})}},45000);return()=>clearInterval(timer)},[snapshot!==null,session?.authenticated,refreshSnapshot]);
  useEffect(()=>{if(!snapshot||!session?.authenticated)return;const timer=setInterval(()=>{void api<Countdown>('power/countdown').then(setCountdown).catch(()=>{})},5000);return()=>clearInterval(timer)},[snapshot!==null,session?.authenticated]);
  useEffect(()=>{if(!dragging)return;const move=(event:PointerEvent)=>setPrefs(previous=>({...previous,width:Math.max(196,Math.min(310,event.clientX))}));const stop=()=>setDragging(false);window.addEventListener('pointermove',move);window.addEventListener('pointerup',stop);document.body.style.cursor='col-resize';document.body.style.userSelect='none';return()=>{window.removeEventListener('pointermove',move);window.removeEventListener('pointerup',stop);document.body.style.cursor='';document.body.style.userSelect=''}},[dragging,setPrefs]);
  const run=async(name:string,operation:()=>Promise<void>)=>{if(busyRef.current)return;busyRef.current=name;setBusy(name);try{await operation()}catch(error){const message=errorMessage(error);setLastFailure(message);notify('操作未完成','error',message);if(error instanceof ApiError&&error.status===401)setSession(null)}finally{busyRef.current=null;setBusy(null)}};
  const applyAction=async(method:string,payload:unknown,title:string)=>{const result=await api<ActionResult>(method,payload);if(result.ok===false)throw new Error(result.message||result.error||'操作未完成，请查看诊断日志。');notify(result.message||title);await refreshSnapshot();return result};
  const connect=async(confirmSwitch=false)=>{
    await run('connect',async()=>{
      if(!snapshot?.accounts.some(account=>account.enabled&&account.has_password)){setAccountEditor(emptyAccount(snapshot?.config.service||''));return}
      const target=snapshot.accounts.find(account=>account.id===accountId);
      if(!confirmSwitch&&target&&status?.portal_online&&status.username&&status.username!==target.username){
        setConfirmation({title:'切换认证账号',description:`当前“${status.username}”正在使用校园网。切换到“${target.label}”会先断开现有会话，再尝试连接。`,action:'确认切换',run:async()=>{setConfirmation(null);await connect(true)}});return;
      }
      const result=await api<ActionResult>('connect',{account_id:accountId||null,force:false,confirm_switch:confirmSwitch});
      if(result.ok===false){setLastFailure(result.message||result.error||'认证失败');throw new Error(result.message||'认证未成功，请检查账号、密码与运营商。')}
      notify(result.message||'校园网已连接');setLastFailure('');await refreshSnapshot();await refreshStatus();
    });
  };
  const disconnect=()=>setConfirmation({title:'断开校园网连接',description:'这会注销当前校园网会话，并暂停自动重连。你可以随时重新连接。',action:'断开连接',danger:true,run:async()=>{setConfirmation(null);await run('disconnect',async()=>{await applyAction('disconnect',{},'已断开连接');await refreshStatus()})}});
  const saveAccount=async()=>{
    if(!accountEditor)return;
    if(!accountEditor.username.trim()){setAccountError('请填写校园网账号。');return}
    if(!accountEditor.id&&!accountEditor.password){setAccountError('请填写校园网密码。');return}
    await run('save-account',async()=>{await api('accounts/save',{...accountEditor,label:accountEditor.label.trim()||accountEditor.username.trim()});await refreshSnapshot();setAccountEditor(null);setAccountError('');notify('账号已保存')});
  };
  const saveOrder=async(ids:string[])=>run('reorder',async()=>{await api('accounts/reorder',{ids});await refreshSnapshot();notify('认证顺序已更新')});
  const toggleAccount=async(account:Account,enabled:boolean)=>run('toggle-account',async()=>{await api('accounts/save',{id:account.id,label:account.label,username:account.username,password:'',service:account.service,enabled,note:account.note});await refreshSnapshot();notify(enabled?'账号已启用':'账号已停用')});
  const deleteAccount=(account:Account)=>setConfirmation({title:'删除校园网账号',description:`确定删除“${account.label}”？本机保存的该账号和密码也会一并删除。`,action:'删除账号',danger:true,run:async()=>{setConfirmation(null);await run('delete-account',async()=>{await api('accounts/delete',{id:account.id});await refreshSnapshot();notify('账号已删除')})}});
  const refreshServices=()=>run('services',async()=>{const values=await api<Service[]>('services');setServices(values);notify(values.length?'运营商服务已更新':'暂未查询到运营商','info',values.length?`可选择 ${values.length} 项服务。`:'连接校园网络后重试，也可以手动输入学校提供的服务名称。')});
  const saveReconnect=async(value:Reconnect)=>run('reconnect',async()=>{await api('reconnect',value);await refreshSnapshot();notify(value.enabled?'自动重连已开启':'自动重连已暂停')});
  const showPower=async(value:Power)=>run('power-preview',async()=>{const plan=await api('power/preview',value);setDetails({title:'电源计划预览',description:'预览不会创建系统任务。确认时间与执行日后，再应用到系统。',text:JSON.stringify(plan,null,2)})});
  const installPower=(value:Power)=>setConfirmation({title:'应用系统电源计划',description:`将在 ${value.shutdown_time} 执行${actionName(value.shutdown_action)}，${value.wake_time} 尝试唤醒。系统计划在应用退出后仍会执行。`,action:'应用到系统',run:async()=>{setConfirmation(null);await run('power-install',async()=>{const result=await api<ActionResult>('power/install',value);if(result.ok===false){setDetails({title:result.permission_error?'需要管理员权限':'电源计划尚未生效',description:result.message||'方案已保存，请按照下方信息完成系统操作。',text:result.admin_command?`${result.admin_command}\n\n待处理方案：${result.pending_config||''}`:JSON.stringify(result,null,2),elevate:isDesktop&&result.permission_error?'install':undefined});notify('电源计划尚未生效','info')}else{setPower(await api<Power>('power'));notify('系统电源计划已应用')}})}});
  const removePower=()=>setConfirmation({title:'移除系统电源计划',description:'移除 CampusAuth 创建的电源任务。校园网认证与账号设置不受影响。',action:'移除计划',run:async()=>{setConfirmation(null);await run('power-remove',async()=>{await applyAction('power/remove',{},'系统电源计划已移除');setPower(await api<Power>('power'))})}});
  const exportDiagnostics=async()=>{setDiagnosticsPreview(true)};
  const confirmExportDiagnostics=()=>run('diagnostics',async()=>{const result=await api<Diagnostics>('diagnostics/export',{});if(isDesktop){const {invoke}=await import('@tauri-apps/api/core');const saved=await invoke<{ok:boolean;canceled?:boolean;path?:string}>('save_diagnostics',{filename:result.filename,content:result.content});if(!saved.canceled)notify('诊断文件已导出','success',saved.path)}else{const blob=new Blob([result.content],{type:result.mime_type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=result.filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('诊断文件已导出')}setDiagnosticsPreview(false)});
  const checkUpdates=()=>run('updates',async()=>{const result=await api<UpdateInfo>('updates/check');setUpdate(result);notify(result.available?`发现新版本 ${result.latest_version}`:result.message||'当前已是最新版本','info')});
  const openRelease=async(url:string)=>{if(isDesktop)await api('app/open-external',{url});else window.open(url,'_blank','noopener,noreferrer')};
  const patchDesktop=async(patch:Partial<DesktopPrefs>)=>run('desktop-preferences',async()=>{setDesktopPrefs(await api<DesktopPrefs>('app/preferences',patch));notify('桌面设置已保存')});
  const goto=(next:Page)=>{setPage(next);setMobileNav(false)};
  const active=navigation.find(item=>item.id===page)!;
  const online=status?.network_online;
  const effectiveUsername=status?.username||'暂无在线账号';
  const school=snapshot?.config.display_name||'CampusAuth';
  const currentFailure=lastFailure||(status?.network_online===false?status.reason:'');
  const activeAccounts=snapshot?.accounts.filter(account=>account.enabled).length||0;
  const uiWidth=prefs.collapsed?76:prefs.width;

  if(!isDesktop&&!session?.authenticated)return <Login session={session} initializing={initializing} onSuccess={()=>void loadApp()}/>;
  return <div className={'app-shell '+(prefs.collapsed?'is-collapsed':'')+(mobileNav?' mobile-nav-open':'')} style={{'--sidebar-width':`${uiWidth}px`} as CSSProperties}>
    <Toaster toasterId={toasterId} position="top-end" pauseOnHover pauseOnWindowBlur/>
    {mobileNav&&<button className="mobile-backdrop" aria-label="关闭导航" onClick={()=>setMobileNav(false)}/>}
    <aside className="sidebar">
      <button className="app-brand" onClick={()=>goto('connection')} aria-label="CampusAuth 首页"><span className="brand-symbol"><PlugConnected20Regular/></span><span className="brand-word">CampusAuth<span>校园网助手</span></span></button>
      <div className="sidebar-section-label">我的设备</div>
      <nav aria-label="主要导航">{navigation.map(item=><Tooltip key={item.id} content={item.label} relationship="label" positioning="after" withArrow><button className={'nav-item '+(page===item.id?'active':'')} onClick={()=>goto(item.id)} aria-current={page===item.id?'page':undefined}><span className="nav-icon">{item.icon}</span><span className="nav-label">{item.label}</span>{page===item.id&&<span className="nav-active-dot"/>}</button></Tooltip>)}</nav>
      <div className="sidebar-bottom">
        <div className="device-block"><span className="device-avatar"><Desktop20Regular/></span><span className="device-copy"><strong>{isDesktop?'本机设备':'服务器管理'}</strong><span>{school}</span></span><span className={'device-dot '+(online?'online':'')}/></div>
        <Divider/>
        <button className="sidebar-collapse" onClick={()=>setPrefs(previous=>({...previous,collapsed:!previous.collapsed}))} title={prefs.collapsed?'展开侧边栏':'收起侧边栏'}><span>{prefs.collapsed?<ChevronDoubleRight20Regular/>:<ChevronDoubleLeft20Regular/>}</span><span className="nav-label">收起侧边栏</span></button>
        <span className="sidebar-version" title={`CampusAuth ${info?.version||'0.3.0'}`}>{prefs.collapsed?'CA':`CampusAuth ${info?.version||'0.3.0'}`}</span>
      </div>
      {!prefs.collapsed&&<div className={'sidebar-resizer '+(dragging?'dragging':'')} role="separator" aria-label="调整侧边栏宽度" aria-orientation="vertical" tabIndex={0} onPointerDown={event=>{event.preventDefault();setDragging(true)}} onKeyDown={event=>{if(event.key==='ArrowRight')setPrefs(p=>({...p,width:Math.min(310,p.width+12)}));if(event.key==='ArrowLeft')setPrefs(p=>({...p,width:Math.max(196,p.width-12)}))}}/>}
    </aside>
    <div className="workspace">
      <header className={'topbar '+(isDesktop?'desktop-titlebar':' ')} data-tauri-drag-region><div className="topbar-left"><IconButton label="打开导航" className="mobile-menu" icon={<Navigation20Regular/>} onClick={()=>setMobileNav(true)}/><span className="breadcrumb">我的设备</span><ChevronRight16Regular/><strong>{active.label}</strong></div><div className="titlebar-drag-space" data-tauri-drag-region/><div className="topbar-right"><span className="school-indicator"><span className="tiny-dot"/>{school}</span><Divider vertical/><IconButton label={dark?'切换浅色模式':'切换深色模式'} icon={dark?<WeatherSunny20Regular/>:<WeatherMoon20Regular/>} onClick={()=>setPrefs(p=>({...p,theme:dark?'light':'dark'}))}/><Menu><MenuTrigger disableButtonEnhancement><Button appearance="subtle" aria-label="更多应用操作" icon={<MoreHorizontal20Regular/>}/></MenuTrigger><MenuPopover><MenuList><MenuItem icon={<DocumentText20Regular/>} onClick={()=>void exportDiagnostics()}>导出诊断</MenuItem><MenuItem icon={<Info20Regular/>} onClick={()=>goto('settings')}>关于 CampusAuth</MenuItem>{!isDesktop&&<MenuItem icon={<SignOut20Regular/>} onClick={()=>void run('logout',async()=>{await api('logout',{});setSession(null)})}>退出管理会话</MenuItem>}{isDesktop&&<MenuItem icon={<DoorArrowRight20Regular/>} onClick={()=>void api('app/quit',{})}>完全退出应用</MenuItem>}</MenuList></MenuPopover></Menu>{isDesktop&&<div className="window-controls"><button aria-label="最小化窗口" onClick={()=>void api('app/window/minimize',{})}><svg viewBox="0 0 16 16"><path d="M3 8h10"/></svg></button><button aria-label={maximized?'还原窗口':'最大化窗口'} onClick={()=>void api<{maximized:boolean}>('app/window/maximize-toggle',{}).then(result=>setMaximized(result.maximized))}><svg viewBox="0 0 16 16">{maximized?<><path d="M5 3h8v8M3 5h8v8H3z"/></>:<path d="M3.5 3.5h9v9h-9z"/>}</svg></button><button className="window-close" aria-label="关闭窗口" onClick={()=>void api('app/window/close',{})}><svg viewBox="0 0 16 16"><path d="m4 4 8 8m0-8-8 8"/></svg></button></div>}</div></header>
      <main className="page-content" key={page}>
        <div className="page-title-row"><div><h1>{active.label}</h1><p>{active.subtitle}</p></div><div className="page-title-action">{page==='connection'&&<Button appearance="secondary" icon={<ArrowClockwise20Regular className={refreshing?'spinning':''}/>} onClick={()=>void refreshStatus()} disabled={refreshing||!!busy}>{refreshing?'检测中':'检测网络'}</Button>}{page==='accounts'&&<Button appearance="primary" icon={<Add20Regular/>} onClick={()=>{setAccountError('');setAccountEditor(emptyAccount(snapshot?.config.service||''))}}>添加账号</Button>}</div></div>
        {initializing?<div className="loading-content"><Spinner label="正在载入本机配置…"/></div>:initialError?<Panel><EmptyState icon={<ErrorCircle20Regular/>} title="暂时无法载入应用" description={initialError} action={<Button appearance="primary" onClick={()=>void loadApp()}>重新载入</Button>}/></Panel>:<>
          {countdown.active&&<MessageBar intent="warning" className="countdown-notice"><MessageBarBody><MessageBarTitle>设备即将{actionName(countdown.action||'suspend')}</MessageBarTitle>预计剩余 {Math.max(0,countdown.remaining_seconds||0)} 秒。<Button appearance="subtle" onClick={()=>void run('cancel-power',async()=>{await applyAction('power/cancel',{},'已取消本次电源操作');setCountdown({ok:true,active:false})})}>取消本次操作</Button></MessageBarBody></MessageBar>}
          {page==='connection'&&<>
            <section className={'connection-hero '+(online?'connected':'')}>
              <div className="hero-main"><div className="network-orbit"><div className="orbit-ring ring-two"/><div className="orbit-ring ring-one"/><div className="orbit-core">{online?<PlugConnected20Regular/>:<PlugDisconnected20Regular/>}</div><span className="orbit-badge">{online?<Checkmark16Regular/>:<Clock20Regular/>}</span></div><div className="hero-copy"><div className="hero-eyebrow"><span className={'tiny-dot '+(online?'success':'')}/>{school}</div><h2>{online?(status?.portal_online===true?'校园网络已连接':'互联网已连接'):online===false?'等待连接校园网':'随时准备，轻松连接'}</h2><p>{online?(status?.portal_online===true?'网络通畅，安心投入你的学习与工作。':'互联网访问正常，校园网认证状态仍待网关确认。'):status?.message||'添加账号，连接学校网络，即可开始认证。'}</p><div className="hero-actions"><Button appearance="primary" size="large" icon={busy==='connect'?<Spinner size="tiny"/>:<PlugConnected20Regular/>} onClick={()=>void connect()} disabled={!!busy}>{busy==='connect'?'正在认证…':online?'检查并连接':'连接校园网'}</Button><Button appearance="transparent" size="large" icon={<PlugDisconnected20Regular/>} onClick={disconnect} disabled={!!busy||!status}>断开连接</Button></div></div></div>
              <div className="hero-bottom"><span><Person20Regular/><span>当前账号</span><strong title={effectiveUsername}>{effectiveUsername}</strong></span><span><Globe20Regular/><span>本机地址</span><strong>{status?.local_ip||'等待检测'}</strong></span><span><Clock20Regular/><span>最近检测</span><strong>{clock(status?.checked_at)}</strong></span></div>
            </section>
            <div className="status-grid"><NetworkTile icon={<Globe20Regular/>} label="互联网" description={online?'可以正常访问外网':online===false?'外网检测未通过':'等待网络检测'} state={online}/><NetworkTile icon={<ShieldCheckmark20Regular/>} label="校园网认证" description={status?.portal_online?'校园认证会话在线':status?.portal_online===false?'尚未建立认证会话':'认证网关尚未返回状态'} state={status?.portal_online} yes="已认证" no="未认证"/><div className="network-tile reconnect-tile"><span className="network-tile-icon"><ArrowClockwise20Regular/></span><div><h3>自动重连</h3><p>{snapshot?.reconnect.enabled?'已开启，断线后尝试恢复':'默认关闭，由你决定'}</p></div><Switch aria-label="首页自动重连" checked={snapshot?.reconnect.enabled||false} disabled={!!busy} onChange={(_,data)=>void saveReconnect({...snapshot!.reconnect,enabled:data.checked})}/></div></div>
            <div className="home-columns"><Panel title="连接偏好" description="选择本次认证使用的账号。" className="connection-preference"><SearchSelect label="认证账号" value={accountId} options={[{value:'',label:'自动选择可用账号'},...(snapshot?.accounts.filter(a=>a.enabled).map(a=>({value:a.id,label:a.label,description:a.username}))||[])]} onChange={setAccountId}/><div className="help-line"><Info20Regular/><span>自动选择会按设置顺序尝试，未设置时按添加顺序。</span></div><Button appearance="subtle" icon={<PersonAccounts20Regular/>} iconPosition="after" onClick={()=>goto('accounts')}>管理 {snapshot?.accounts.length||0} 个账号</Button></Panel><Panel title="最近活动" actions={<Button appearance="subtle" size="small" onClick={()=>setDetails({title:'运行日志',description:'最近 7 天的运行记录，导出时会脱敏。',text:snapshot?.logs.join('\n')||'暂无运行日志。'})}>查看全部</Button>} className="recent-panel"><div className="activity-list">{snapshot?.logs.length?snapshot.logs.slice(-3).reverse().map((entry,index)=><div className="activity-row" key={index}><span className={'activity-dot '+(!index?'latest':'')}/><span>{entry}</span></div>):<p className="muted">应用已就绪，连接后会显示运行记录。</p>}</div><div className="activity-foot"><span className="tiny-dot success"/>账号与配置保存在{isDesktop?'这台设备':'服务器'}中</div></Panel></div>
            {currentFailure&&<MessageBar intent="warning"><MessageBarBody><MessageBarTitle>最近一次连接未完成</MessageBarTitle>{currentFailure}<Button appearance="subtle" size="small" onClick={()=>void exportDiagnostics()}>导出诊断</Button></MessageBarBody></MessageBar>}
          </>}
          {page==='accounts'&&<AccountsPage accounts={snapshot?.accounts||[]} active={activeAccounts} busy={!!busy} onEdit={account=>{setAccountError('');setAccountEditor({...account,password:''})}} onToggle={toggleAccount} onDelete={deleteAccount} onOrder={saveOrder} onAdd={()=>setAccountEditor(emptyAccount(snapshot?.config.service||''))}/>}
          {page==='reconnect'&&<ReconnectPage value={snapshot?.reconnect||{enabled:false,interval_seconds:180,fail_threshold:3}} busy={!!busy} onSave={saveReconnect}/>}
          {page==='power'&&<PowerPage value={power} busy={!!busy} onPreview={showPower} onApply={installPower} onRemove={removePower}/>}
          {page==='settings'&&<SettingsPage config={snapshot?.config||defaultConnection} profiles={profiles} prefs={prefs} setPrefs={setPrefs} desktopPrefs={desktopPrefs} patchDesktop={patchDesktop} info={info} busy={busy} onSaveConnection={value=>run('connection',async()=>{await api('connection',value);await refreshSnapshot();notify('学校与连接设置已保存')})} onExport={exportDiagnostics} onCheckUpdate={checkUpdates} update={update} onOpenRelease={openRelease} onDetails={setDetails} onOnboarding={()=>setOnboarding(true)}/>}
        </>}
      </main>
    </div>
    {accountEditor&&<Modal title={accountEditor.id?'编辑账号':'添加校园网账号'} description="密码只用于校园网认证，不会出现在列表或诊断文件中。" open onClose={()=>{if(!busy)setAccountEditor(null)}} actions={<><Button onClick={()=>setAccountEditor(null)} disabled={!!busy}>取消</Button><Button appearance="primary" onClick={()=>void saveAccount()} disabled={!!busy}>{busy==='save-account'?<Spinner size="tiny"/>:'保存账号'}</Button></>}><div className="form-stack">{accountError&&<MessageBar intent="error"><MessageBarBody>{accountError}</MessageBarBody></MessageBar>}<Field label="备注名称"><Input value={accountEditor.label} onChange={(_,data)=>setAccountEditor({...accountEditor,label:data.value})} placeholder="例如：我的校园网"/></Field><Field label="校园网账号" required><Input value={accountEditor.username} onChange={(_,data)=>setAccountEditor({...accountEditor,username:data.value})} placeholder="学号或校园网账号" autoComplete="off"/></Field><Field label="校园网密码" required={!accountEditor.id}><PasswordInput value={accountEditor.password} onChange={value=>setAccountEditor({...accountEditor,password:value})} placeholder={accountEditor.id?'留空保留已保存密码':'请输入校园网密码'}/></Field><div className="field-with-action"><SearchSelect label="运营商服务" value={accountEditor.service} options={serviceOptions(services,accountEditor.service)} onChange={value=>setAccountEditor({...accountEditor,service:value})} freeform/><IconButton label="查询校园网运营商" icon={<ArrowClockwise20Regular/>} onClick={()=>void refreshServices()} disabled={!!busy}/></div><Field label="备注"><Input value={accountEditor.note} onChange={(_,data)=>setAccountEditor({...accountEditor,note:data.value})} placeholder="选填"/></Field><Switch checked={accountEditor.enabled} label="启用此账号" onChange={(_,data)=>setAccountEditor({...accountEditor,enabled:data.checked})}/></div></Modal>}
    {confirmation&&<ConfirmDialog {...confirmation} busy={!!busy} onConfirm={()=>void confirmation.run()} onClose={()=>setConfirmation(null)}/>}
    {diagnosticsPreview&&<Modal title="导出诊断前，确认这些内容" description="诊断文件仅保存在你选择的位置。你可以检查后再决定是否分享。" open onClose={()=>setDiagnosticsPreview(false)} actions={<><Button onClick={()=>setDiagnosticsPreview(false)} disabled={!!busy}>取消</Button><Button appearance="primary" icon={<ArrowDownload20Regular/>} disabled={!!busy} onClick={()=>void confirmExportDiagnostics()}>{busy==='diagnostics'?'正在生成…':'确认导出'}</Button></>}><div className="diagnostic-preview"><div><CheckmarkCircle20Regular/><span><strong>应用与系统信息</strong><small>应用版本、平台与运行方式</small></span></div><div><CheckmarkCircle20Regular/><span><strong>连接与配置信息</strong><small>学校、网关、网络状态及脱敏账号配置</small></span></div><div><CheckmarkCircle20Regular/><span><strong>最近 7 天运行日志</strong><small>认证过程、重连记录与错误信息</small></span></div></div><MessageBar intent="info"><MessageBarBody>密码、会话令牌及认证参数会自动隐藏。导出前不需要提供真实密码。</MessageBarBody></MessageBar></Modal>}
    {details&&<Modal title={details.title} description={details.description} open onClose={()=>setDetails(null)} wide actions={<><Button onClick={()=>{void navigator.clipboard.writeText(details.text);notify('已复制到剪贴板')}}>复制内容</Button>{details.elevate&&<Button appearance="primary" disabled={!!busy} onClick={()=>void run('power-elevate',async()=>{const result=await api<ActionResult>('app/power-elevate',{action:details.elevate});if(!result.ok)throw new Error(result.message||'系统未授予权限。');setPower(await api<Power>('power'));setDetails(null);notify('系统电源计划已更新')})}>以管理员权限应用</Button>}<Button appearance={details.elevate?'secondary':'primary'} onClick={()=>setDetails(null)}>完成</Button></>}><pre className="details-text">{details.text}</pre></Modal>}
    {onboarding&&snapshot&&<Onboarding initial={snapshot.config} profiles={profiles} services={services} onServices={async()=>{const values=await api<Service[]>('services');setServices(values);return values}} onFinish={async(config,account,reconnect)=>{await api('connection',config);await api('accounts/save',account);await api('reconnect',reconnect);localStorage.setItem('campusauth-onboarded','1');setOnboarding(false);await refreshSnapshot();await refreshStatus();notify('准备就绪，欢迎使用 CampusAuth')}} onTest={async(config,account)=>{await api('connection',config);const saved=await api<Account>('accounts/save',account);const result=await api<ActionResult>('connect',{account_id:saved.id||null,force:false});return{...result,account_id:saved.id}}} onClose={()=>{localStorage.setItem('campusauth-onboarded','1');setOnboarding(false)}}/>}
  </div>;
}

function NetworkTile({icon,label,description,state,yes,no}:{icon:ReactNode;label:string;description:string;state:boolean|null|undefined;yes?:string;no?:string}){return <div className="network-tile"><span className="network-tile-icon">{icon}</span><div><h3>{label}</h3><p>{description}</p></div><StatusBadge state={state} yes={yes} no={no}/></div>}
function serviceOptions(services:Service[],current=''){const values=services.length?services:[{value:'校园移动',name:'校园移动'},{value:'校园联通',name:'校园联通'},{value:'校园电信',name:'校园电信'},{value:'[-1-1]系统默认服务[-1-1]',name:'系统默认服务'}];const all=current&&!values.some(s=>s.value===current)?[{value:current,name:current},...values]:values;return all.map(service=>({value:service.value,label:service.name}))}
function actionName(action:string){return action==='shutdown'?'关机':action==='hibernate'?'休眠':'睡眠'}

function AccountsPage({accounts,active,busy,onEdit,onToggle,onDelete,onOrder,onAdd}:{accounts:Account[];active:number;busy:boolean;onEdit:(account:Account)=>void;onToggle:(account:Account,enabled:boolean)=>Promise<unknown>;onDelete:(account:Account)=>void;onOrder:(ids:string[])=>Promise<unknown>;onAdd:()=>void}){
  const [query,setQuery]=useState('');const [filter,setFilter]=useState('all');
  const sensors=useSensors(useSensor(PointerSensor,{activationConstraint:{distance:7}}),useSensor(KeyboardSensor,{coordinateGetter:sortableKeyboardCoordinates}));
  const visible=accounts.filter(account=>(filter==='all'||(filter==='enabled'?account.enabled:!account.enabled))&&`${account.label} ${account.username} ${account.service}`.toLowerCase().includes(query.toLowerCase()));
  const move=(account:Account,direction:number)=>{const index=accounts.findIndex(item=>item.id===account.id);const next=index+direction;if(next>=0&&next<accounts.length)void onOrder(arrayMove(accounts,index,next).map(item=>item.id))};
  const dragEnd=(event:DragEndEvent)=>{if(!event.over||event.active.id===event.over.id)return;const from=accounts.findIndex(a=>a.id===event.active.id),to=accounts.findIndex(a=>a.id===event.over!.id);if(from>=0&&to>=0)void onOrder(arrayMove(accounts,from,to).map(item=>item.id))};
  return <>
    <div className="accounts-toolbar"><TabList selectedValue={filter} onTabSelect={(_,data)=>setFilter(String(data.value))}><Tab value="all">全部账号 <span className="tab-count">{accounts.length}</span></Tab><Tab value="enabled">已启用 <span className="tab-count">{active}</span></Tab><Tab value="disabled">已停用</Tab></TabList><Input value={query} onChange={(_,data)=>setQuery(data.value)} contentBefore={<Search20Regular/>} placeholder="搜索名称、账号或运营商" aria-label="搜索账号" className="account-search"/></div>
    <div className="account-order-hint"><ArrowSort20Regular/><span>拖动左侧手柄调整认证顺序，也可以使用上下移动。未设置时按添加顺序。</span></div>
    {visible.length?<DndContext sensors={sensors} collisionDetection={closestCenter} onDragEnd={dragEnd}><SortableContext items={visible.map(account=>account.id)} strategy={verticalListSortingStrategy}><div className="account-list">{visible.map(account=><SortableAccount key={account.id} account={account} index={accounts.findIndex(a=>a.id===account.id)} total={accounts.length} busy={busy} onEdit={onEdit} onToggle={onToggle} onDelete={onDelete} onMove={move}/>)}</div></SortableContext></DndContext>:<Panel><EmptyState icon={<PersonAccounts20Regular/>} title={accounts.length?'没有匹配的账号':'添加你的第一个账号'} description={accounts.length?'试试其他关键词，或切换账号筛选。':'保存校园网账号与密码，即可开始自动认证。'} action={!accounts.length&&<Button appearance="primary" icon={<Add20Regular/>} onClick={onAdd}>添加账号</Button>}/></Panel>}
    <div className="account-security"><ShieldCheckmark20Regular/><p>账号密码保存在设备本地，列表与诊断导出中均不会显示密码。停用的账号会在自动认证时跳过。</p></div>
  </>;
}
function SortableAccount({account,index,total,busy,onEdit,onToggle,onDelete,onMove}:{account:Account;index:number;total:number;busy:boolean;onEdit:(account:Account)=>void;onToggle:(account:Account,enabled:boolean)=>Promise<unknown>;onDelete:(account:Account)=>void;onMove:(account:Account,direction:number)=>void}){
  const {attributes,listeners,setNodeRef,transform,transition,isDragging}=useSortable({id:account.id,disabled:busy});
  return <article ref={setNodeRef} style={{transform:CSS.Transform.toString(transform),transition}} className={'account-card '+(!account.enabled?'disabled':'')+(isDragging?' dragging':'')}>
    <button className="drag-handle" aria-label={`拖动排序 ${account.label}`} {...attributes} {...listeners}><GridDots20Regular/></button>
    <span className="account-order">{String(index+1).padStart(2,'0')}</span><span className="account-avatar"><Person20Regular/></span>
    <div className="account-identity"><div><h3>{account.label}</h3>{index===0&&account.enabled&&<Badge appearance="tint" color="brand" size="small">优先认证</Badge>}</div><p>{account.username}</p></div>
    <div className="account-service"><span>{account.service==='[-1-1]系统默认服务[-1-1]'?'系统默认服务':account.service}</span><small>{account.last_ok===true?'上次认证成功':account.last_ok===false?'上次认证未成功':account.note||'尚未认证'}</small></div>
    <Tooltip content={account.enabled?'停用账号':'启用账号'} relationship="label"><Switch aria-label={`${account.label} 启用状态`} checked={account.enabled} onChange={(_,data)=>void onToggle(account,data.checked)} disabled={busy}/></Tooltip>
    <IconButton label={`编辑 ${account.label}`} icon={<Edit20Regular/>} onClick={()=>onEdit(account)} disabled={busy}/>
    <Menu><MenuTrigger disableButtonEnhancement><Button appearance="subtle" aria-label={`${account.label} 更多操作`} icon={<MoreHorizontal20Regular/>} disabled={busy}/></MenuTrigger><MenuPopover><MenuList><MenuItem icon={<ArrowUp20Regular/>} disabled={index===0} onClick={()=>onMove(account,-1)}>上移一位</MenuItem><MenuItem icon={<ArrowDown20Regular/>} disabled={index===total-1} onClick={()=>onMove(account,1)}>下移一位</MenuItem><MenuItem icon={<Edit20Regular/>} onClick={()=>onEdit(account)}>编辑账号</MenuItem><MenuItem icon={<Delete20Regular/>} className="danger-text" onClick={()=>onDelete(account)}>删除账号</MenuItem></MenuList></MenuPopover></Menu>
  </article>;
}

function ReconnectPage({value,busy,onSave}:{value:Reconnect;busy:boolean;onSave:(value:Reconnect)=>Promise<unknown>}){
  const [draft,setDraft]=useState(value);
  useEffect(()=>setDraft(value),[value]);
  return <><section className="feature-banner"><span className="feature-icon"><ArrowClockwise20Regular/></span><div><Badge appearance="tint" color={value.enabled?'success':'informative'}>{value.enabled?'正在守护连接':'当前已关闭'}</Badge><h2>断线之后，自动接上。</h2><p>连续检测失败时，使用已启用的账号恢复校园网连接。</p></div><Switch aria-label="启用自动重连" checked={draft.enabled} onChange={(_,data)=>setDraft({...draft,enabled:data.checked})}/></section><Panel title="重连规则" description="稍作等待，避免网络短暂波动时频繁认证。"><div className="form-grid reconnect-form"><Field label="检查间隔" hint="每隔多久检查一次互联网连接。"><Input type="number" value={String(draft.interval_seconds)} min={10} max={86400} contentAfter="秒" disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,interval_seconds:Number(data.value)})}/></Field><Field label="连续失败次数" hint="达到次数后，才会尝试重新认证。"><Input type="number" value={String(draft.fail_threshold)} min={1} max={10} contentAfter="次" disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,fail_threshold:Number(data.value)})}/></Field></div><Divider/><div className="panel-actions"><span className="muted">推荐设置：180 秒检查，连续失败 3 次后重连。</span><Button appearance="primary" disabled={busy||draft.interval_seconds<10||draft.interval_seconds>86400||draft.fail_threshold<1||draft.fail_threshold>10} onClick={()=>void onSave(draft)}>保存重连设置</Button></div></Panel><div className="explanation-block"><Info20Regular/><div><h3>运行方式</h3><p>{isDesktop?'关闭窗口后，如果应用保留在系统托盘，自动重连会继续运行。完全退出应用后，自动重连停止。':'服务器服务运行期间会持续检查网络。退出管理页面不会停止服务。'}</p><p>主动断开校园网时，自动重连会同时暂停，避免立即重新登录。</p></div></div></>;
}

function PowerPage({value,busy,onPreview,onApply,onRemove}:{value:Power;busy:boolean;onPreview:(value:Power)=>Promise<unknown>;onApply:(value:Power)=>void;onRemove:()=>void}){
  const [draft,setDraft]=useState(value);useEffect(()=>setDraft(value),[value]);
  const valid=/^([01]\d|2[0-3]):[0-5]\d$/.test(draft.shutdown_time)&&/^([01]\d|2[0-3]):[0-5]\d$/.test(draft.wake_time)&&draft.days.length>0;
  return <><MessageBar intent={value.enabled?'success':'info'}><MessageBarBody><MessageBarTitle>{value.enabled?'系统计划已启用':'电源计划默认关闭'}</MessageBarTitle>{value.enabled?'计划在应用完全退出后仍会执行。':'只有明确点击“应用到系统”后，才会创建定时任务。'}</MessageBarBody></MessageBar><Panel title="定时安排" description="睡眠、休眠或关机，由你选择。" actions={<Switch aria-label="启用电源计划" checked={draft.enabled} onChange={(_,data)=>setDraft({...draft,enabled:data.checked})}/>}><div className={'power-fields '+(!draft.enabled?'inactive':'')}><div className="form-grid"><Field label="执行动作"><Select value={draft.shutdown_action} disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,shutdown_action:data.value})}><option value="suspend">睡眠</option><option value="hibernate">休眠</option><option value="shutdown">关机</option></Select></Field><Field label="执行时间"><Input type="time" value={draft.shutdown_time} disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,shutdown_time:data.value})}/></Field><Field label="唤醒时间"><Input type="time" value={draft.wake_time} disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,wake_time:data.value})}/></Field><Field label="唤醒方式"><Select value={draft.wake_method} disabled={!draft.enabled} onChange={(_,data)=>setDraft({...draft,wake_method:data.value})}><option value="timer">系统唤醒定时器</option><option value="rtc">硬件 RTC 唤醒（Linux）</option></Select></Field></div><Field label="重复日期"><div className="weekday-select">{weekdays.map(([id,label])=><button key={id} disabled={!draft.enabled} aria-pressed={draft.days.includes(id)} onClick={()=>setDraft({...draft,days:draft.days.includes(id)?draft.days.filter(day=>day!==id):[...draft.days,id]})}>{label}</button>)}</div></Field><SettingRow title="执行前等待" description="在此期间可以取消本次电源操作。"><Input type="number" min={0} max={3600} value={String(draft.shutdown_delay_seconds)} disabled={!draft.enabled} contentAfter="秒" onChange={(_,data)=>setDraft({...draft,shutdown_delay_seconds:Number(data.value)})}/></SettingRow></div><Divider/><div className="panel-actions"><Button appearance="subtle" icon={<Delete20Regular/>} disabled={busy} onClick={onRemove}>移除系统计划</Button><div><Button icon={<Eye20Regular/>} onClick={()=>void onPreview(draft)} disabled={busy||!valid}>预览计划</Button><Button appearance="primary" disabled={busy||!draft.enabled||!valid} onClick={()=>onApply(draft)}>应用到系统</Button></div></div></Panel><div className="explanation-block"><Clock20Regular/><div><h3>关于自动唤醒</h3><p>睡眠或休眠唤醒取决于硬件和系统支持。完全关机后的自动开机，通常需要在 BIOS / UEFI 中配置 RTC。应用系统任务需要管理员权限。</p><p>首次使用建议先预览安排，再在设备上测试一个方便观察的时间。</p></div></div></>;
}

function SettingsPage({config,profiles,prefs,setPrefs,desktopPrefs,patchDesktop,info,busy,onSaveConnection,onExport,onCheckUpdate,update,onOpenRelease,onDetails,onOnboarding}:{config:Connection;profiles:Profile[];prefs:UiPrefs;setPrefs:React.Dispatch<React.SetStateAction<UiPrefs>>;desktopPrefs:DesktopPrefs;patchDesktop:(value:Partial<DesktopPrefs>)=>Promise<unknown>;info:AppInfo|null;busy:string|null;onSaveConnection:(value:Connection)=>Promise<unknown>;onExport:()=>Promise<unknown>;onCheckUpdate:()=>Promise<unknown>;update:UpdateInfo|null;onOpenRelease:(url:string)=>Promise<unknown>;onDetails:(value:{title:string;description:string;text:string})=>void;onOnboarding:()=>void}){
  const [section,setSection]=useState('general');const [draft,setDraft]=useState(config);const [probes,setProbes]=useState(config.probe_urls.join('\n'));const [discovery,setDiscovery]=useState(config.discovery_urls.join('\n'));
  useEffect(()=>{setDraft(config);setProbes(config.probe_urls.join('\n'));setDiscovery(config.discovery_urls.join('\n'))},[config]);
  const changeSchool=(id:string)=>{const profile=profiles.find(profile=>profile.id===id);if(profile){setDraft(profile.config);setProbes(profile.config.probe_urls.join('\n'));setDiscovery(profile.config.discovery_urls.join('\n'))}};
  return <><TabList selectedValue={section} onTabSelect={(_,data)=>setSection(String(data.value))} className="settings-tabs"><Tab value="general">常规</Tab><Tab value="school">学校与连接</Tab><Tab value="diagnostics">诊断与更新</Tab></TabList>{section==='general'&&<><Panel title="外观" description="选择适合这台设备的界面风格。"><SettingRow title="应用主题" description="浅色、深色，或跟随系统自动切换。"><Select aria-label="应用主题" value={prefs.theme} onChange={(_,data)=>setPrefs({...prefs,theme:data.value as Theme})}><option value="system">跟随系统</option><option value="light">浅色模式</option><option value="dark">深色模式</option></Select></SettingRow><div className="text-size-setting"><div className="text-size-heading"><div><h3>文字大小</h3><p>即时调整整套界面的文字与控件，不改变系统缩放。</p></div><Button appearance="subtle" onClick={()=>setPrefs({...prefs,textSize:15})}>恢复默认</Button></div><div className="text-size-presets">{[[13,'紧凑'],[15,'标准'],[17,'大号'],[19,'特大']].map(([size,label])=><button key={size} type="button" aria-pressed={prefs.textSize===size} onClick={()=>setPrefs({...prefs,textSize:Number(size)})}>{label}</button>)}</div><div className="text-size-slider"><span>小</span><Slider aria-label="文字大小" min={13} max={20} step={1} value={prefs.textSize} onChange={(_,data)=>setPrefs({...prefs,textSize:data.value})}/><span>大</span><output>{prefs.textSize}</output></div><div className="text-size-preview"><strong>让校园网络，随时在线。</strong><span>这是正文与辅助说明的实时预览。</span></div></div><ToggleRow title="收起侧边栏" description="保留图标，腾出更多内容空间。" checked={prefs.collapsed} onChange={value=>setPrefs({...prefs,collapsed:value})}/></Panel>{isDesktop&&<Panel title="桌面行为" description="开机启动与托盘运行均由你控制。"><ToggleRow title="开机启动" description="登录系统后自动打开 CampusAuth。" checked={desktopPrefs.autostart} onChange={value=>void patchDesktop({autostart:value})} disabled={!!busy}/><ToggleRow title="关闭窗口时保留在托盘" description="自动重连继续运行；可从托盘菜单完全退出。" checked={desktopPrefs.close_to_tray} onChange={value=>void patchDesktop({close_to_tray:value})} disabled={!!busy}/><ToggleRow title="最小化到系统托盘" checked={desktopPrefs.minimize_to_tray} onChange={value=>void patchDesktop({minimize_to_tray:value})} disabled={!!busy}/></Panel>}<Panel title="本机数据"><SettingRow title="数据目录" description={info?.data_dir||'账号、配置与日志保存在应用数据目录中。'}><Button onClick={()=>{if(info?.data_dir)void navigator.clipboard.writeText(info.data_dir)}} disabled={!info?.data_dir}>复制路径</Button></SettingRow><SettingRow title="重新进行使用引导" description="依次设置学校、账号、运营商与自动重连。"><Button onClick={onOnboarding}>打开引导</Button></SettingRow></Panel><Panel title="关于 CampusAuth"><div className="about-block"><span className="brand-symbol"><PlugConnected20Regular/></span><div><h3>CampusAuth <Badge appearance="outline">{info?.version||'0.3.0'}</Badge></h3><p>独立校园网助手 · 锐捷 ePortal / SAM+</p><small>内置青海大学；其他学校可自定义参数，需在目标网络验证。</small><div className="author-line"><span>作者 <strong>fulao</strong></span><a href="https://fulao.cc" target="_blank" rel="noopener noreferrer" onClick={event=>{if(isDesktop){event.preventDefault();void onOpenRelease('https://fulao.cc')}}}>博客 fulao.cc</a></div></div></div><Divider/><div className="about-links"><Button appearance="subtle" onClick={()=>void onOpenRelease('https://github.com/fulaoaz/CampusAuth')}>项目仓库</Button><Button appearance="subtle" onClick={()=>onDetails({title:'便携使用与卸载',description:'清理前请先移除已启用的系统任务。',text:'1. 在“电源计划”中移除系统计划。\n2. 如果启用了开机启动，请先关闭。\n3. 从托盘菜单完全退出 CampusAuth。\n4. 删除便携应用文件，或通过系统“应用与功能”卸载安装版。\n5. 如需清除账号与配置，退出后删除应用数据目录。'})}>使用与卸载说明</Button><Button appearance="subtle" onClick={()=>onDetails({title:'开源组件许可',description:'完整第三方许可随发行包附带。',text:'CampusAuth：MIT License\nRust、Tauri：MIT / Apache-2.0\nReact：MIT\nFluent UI React：MIT\nFluent UI System Icons：MIT\nNoto Sans SC：SIL Open Font License 1.1\n\n所有应用资源随包提供，无需加载在线字体或图标。'})}>开源许可</Button></div></Panel></>}
    {section==='school'&&<Panel title="学校与认证参数" description="使用内置预设，或填写所在学校的 ePortal 参数。"><div className="form-stack"><SearchSelect label="学校预设" value={draft.profile_id} options={profiles.map(profile=>({value:profile.id,label:profile.name,description:profile.description}))} onChange={changeSchool}/><div className="form-grid"><Field label="学校名称"><Input value={draft.display_name} onChange={(_,data)=>setDraft({...draft,display_name:data.value})}/></Field><Field label="认证网关" required><Input value={draft.gateway} onChange={(_,data)=>setDraft({...draft,gateway:data.value})} placeholder="http://学校认证网关"/></Field><Field label="默认运营商服务"><Input value={draft.service} onChange={(_,data)=>setDraft({...draft,service:data.value})}/></Field><Field label="用户组" hint="学校未要求时可留空。"><Input value={draft.user_group} onChange={(_,data)=>setDraft({...draft,user_group:data.value})}/></Field></div><details className="advanced-settings"><summary>高级连接设置</summary><div className="form-stack"><Field label="外网探测地址" hint="每行一个 HTTP / HTTPS 地址。"><Textarea value={probes} onChange={(_,data)=>setProbes(data.value)} resize="vertical" rows={3}/></Field><Field label="认证页发现地址"><Textarea value={discovery} onChange={(_,data)=>setDiscovery(data.value)} resize="vertical" rows={2}/></Field><div className="form-grid"><Field label="请求超时"><Input type="number" value={String(draft.timeout_seconds)} min={2} max={30} contentAfter="秒" onChange={(_,data)=>setDraft({...draft,timeout_seconds:Number(data.value)})}/></Field><Field label="每账号重试"><Input type="number" value={String(draft.retry_per_account)} min={1} max={5} contentAfter="次" onChange={(_,data)=>setDraft({...draft,retry_per_account:Number(data.value)})}/></Field></div></div></details><div className="panel-actions"><span className="muted">保存设置不会立即断开当前认证会话。</span><Button appearance="primary" disabled={!!busy||!draft.gateway} onClick={()=>void onSaveConnection({...draft,probe_urls:probes.split('\n').map(s=>s.trim()).filter(Boolean),discovery_urls:discovery.split('\n').map(s=>s.trim()).filter(Boolean)})}>保存连接设置</Button></div></div></Panel>}
    {section==='diagnostics'&&<><Panel title="运行诊断" description="日志保留最近 7 天，导出时自动隐藏密码与认证令牌。"><SettingRow title="导出诊断文件" description="包含版本、网络状态、脱敏配置和运行日志，方便定位问题。"><Button icon={<ArrowDownload20Regular/>} onClick={()=>void onExport()} disabled={!!busy}>{busy==='diagnostics'?'正在导出…':'导出诊断'}</Button></SettingRow></Panel><Panel title="应用更新" description="你决定何时检查、下载与安装新版本。"><SettingRow title={`当前版本 ${info?.version||'0.3.0'}`} description={update?.message||'不会自动下载或静默安装更新。'}><Button icon={<ArrowClockwise20Regular/>} onClick={()=>void onCheckUpdate()} disabled={!!busy}>{busy==='updates'?'正在检查…':'检查更新'}</Button></SettingRow>{update?.available&&<div className="update-result"><CheckmarkCircle20Regular/><div><h3>新版本 {update.latest_version}</h3><p>{update.notes||'查看发布页了解更新内容。'}</p></div><Button appearance="primary" onClick={()=>void onOpenRelease(update.release_url||'https://github.com/fulaoaz/CampusAuth/releases')}>查看并下载</Button></div>}</Panel></>}
  </>;
}

function Login({session,initializing,onSuccess}:{session:Session|null;initializing:boolean;onSuccess:()=>void}){
  const [password,setPassword]=useState('');const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const login=async(event:React.FormEvent)=>{event.preventDefault();setBusy(true);setError('');try{const result=await api<ActionResult>('login',{password});if(!result.ok)throw new Error(result.message||'密码不正确。');onSuccess()}catch(error){setError(errorMessage(error))}finally{setBusy(false)}};
  return <div className="login-page"><div className="login-brand"><span className="brand-symbol"><PlugConnected20Regular/></span><strong>CampusAuth</strong></div><div className="login-card"><span className="login-icon"><ShieldCheckmark20Regular/></span><h1>管理你的校园网连接</h1><p>输入服务器管理员密码，安全地访问设备。</p>{initializing?<Spinner label="正在检查管理会话…"/>:session?.setup_required?<MessageBar intent="info"><MessageBarBody><MessageBarTitle>请先设置管理员密码</MessageBarTitle>在服务器本机运行 TUI，完成管理员密码设置后，刷新此页面。</MessageBarBody></MessageBar>:<form onSubmit={event=>void login(event)}><Field label="管理员密码" required><PasswordInput value={password} onChange={setPassword} placeholder="请输入管理员密码"/></Field>{error&&<MessageBar intent="error"><MessageBarBody>{error}</MessageBarBody></MessageBar>}<Button type="submit" appearance="primary" size="large" disabled={busy||!password}>{busy?<Spinner size="tiny"/>:'登录管理台'}</Button></form>}<div className="login-foot"><LockClosed20Regular/>管理会话仅用于这台服务器</div></div><span className="login-caption">CampusAuth · 校园网助手</span></div>;
}

function Onboarding({initial,profiles,services,onServices,onFinish,onTest,onClose}:{initial:Connection;profiles:Profile[];services:Service[];onServices:()=>Promise<Service[]>;onFinish:(config:Connection,account:AccountInput,reconnect:Reconnect)=>Promise<void>;onTest:(config:Connection,account:AccountInput)=>Promise<ActionResult>;onClose:()=>void}){
  const [step,setStep]=useState(0);const [config,setConfig]=useState(initial);const [account,setAccount]=useState(emptyAccount(initial.service));const [reconnect,setReconnect]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [test,setTest]=useState<ActionResult|null>(null);const [testedAccount,setTestedAccount]=useState<AccountInput|null>(null);
  const labels=['选择学校','添加账号','运营商服务','测试连接','自动重连'];
  const valid=step===0?!!config.gateway:step===1?!!account.username.trim()&&!!account.password:step===2?!!account.service:true;
  const next=async()=>{if(!valid)return;setError('');if(step<4){setStep(step+1);return}setBusy(true);try{await onFinish(config,testedAccount||account,{enabled:reconnect,interval_seconds:180,fail_threshold:3})}catch(error){setError(errorMessage(error))}finally{setBusy(false)}};
  const testConnection=async()=>{setBusy(true);setError('');try{const result=await onTest(config,testedAccount||account);setTest(result);setTestedAccount({...account,id:typeof result.account_id==='string'?result.account_id:testedAccount?.id})}catch(error){setError(errorMessage(error))}finally{setBusy(false)}};
  return <Modal title="欢迎使用 CampusAuth" description="几步设置，让校园网连接更省心。" open onClose={onClose} wide actions={<><Button appearance="subtle" onClick={onClose} disabled={busy}>稍后设置</Button><div className="onboarding-buttons">{step>0&&<Button icon={<ArrowLeft20Regular/>} onClick={()=>setStep(step-1)} disabled={busy}>上一步</Button>}<Button appearance="primary" icon={step<4?<ArrowRight20Regular/>:<Checkmark16Regular/>} iconPosition="after" onClick={()=>void next()} disabled={!valid||busy}>{busy?'正在处理…':step===4?'完成设置':'继续'}</Button></div></>}><div className="onboarding-progress">{labels.map((label,index)=><div key={label} className={index===step?'current':index<step?'done':''}><span>{index<step?<Checkmark16Regular/>:index+1}</span><small>{label}</small></div>)}</div><ProgressBar value={(step+1)/5} thickness="medium"/><div className="onboarding-body">{error&&<MessageBar intent="error"><MessageBarBody>{error}</MessageBarBody></MessageBar>}
    {step===0&&<div className="form-stack"><h2>先告诉我们，你在哪所学校。</h2><SearchSelect label="选择学校" value={config.profile_id} options={profiles.map(profile=>({value:profile.id,label:profile.name,description:profile.description}))} onChange={value=>{const profile=profiles.find(profile=>profile.id===value);if(profile){setConfig(profile.config);setAccount({...account,service:profile.config.service})}}}/>{config.profile_id==='custom'&&<><Field label="学校名称"><Input value={config.display_name} onChange={(_,data)=>setConfig({...config,display_name:data.value})}/></Field><Field label="认证网关" required><Input value={config.gateway} onChange={(_,data)=>setConfig({...config,gateway:data.value})} placeholder="http://学校认证网关"/></Field></>}<p className="muted">内置青海大学配置，其他学校支持自定义兼容的锐捷 ePortal 参数。</p></div>}
    {step===1&&<div className="form-stack"><h2>添加你的校园网账号。</h2><Field label="备注名称"><Input value={account.label} onChange={(_,data)=>setAccount({...account,label:data.value})} placeholder="例如：我的校园网"/></Field><Field label="校园网账号" required><Input value={account.username} onChange={(_,data)=>setAccount({...account,username:data.value})} placeholder="学号或校园网账号"/></Field><Field label="校园网密码" required><PasswordInput value={account.password} onChange={value=>setAccount({...account,password:value})}/></Field><div className="help-line"><LockClosed20Regular/>账号密码只保存在设备本地。</div></div>}
    {step===2&&<div className="form-stack"><h2>选择你的运营商服务。</h2><SearchSelect label="运营商服务" value={account.service} options={serviceOptions(services,account.service)} onChange={value=>setAccount({...account,service:value})} freeform/><Button icon={<ArrowClockwise20Regular/>} onClick={()=>{setBusy(true);void onServices().catch(error=>setError(errorMessage(error))).finally(()=>setBusy(false))}} disabled={busy}>从校园网查询服务</Button><p className="muted">请使用学校认证页面上显示的服务名称，也可以手动输入。</p></div>}
    {step===3&&<div className="onboarding-test"><span className={'test-mark '+(test?.ok?'success':'')}><PlugConnected20Regular/></span><h2>{test?.ok?'连接成功，准备就绪。':'试着连接一次校园网。'}</h2><p>{test?.message||'测试会保存账号，并尝试认证。请先连上学校的有线或无线网络。'}</p><Button appearance="primary" icon={busy?<Spinner size="tiny"/>:<PlugConnected20Regular/>} disabled={busy} onClick={()=>void testConnection()}>{test?'重新测试':'测试连接'}</Button><small>暂时不在校园网内，也可以继续完成设置。</small></div>}
    {step===4&&<div className="onboarding-test"><span className="test-mark"><ArrowClockwise20Regular/></span><h2>需要自动保持连接吗？</h2><p>开启后，每 180 秒检查网络，连续失败 3 次后尝试重新认证。你随时可以暂停。</p><div className="onboarding-toggle"><Switch checked={reconnect} label="开启自动重连" onChange={(_,data)=>setReconnect(data.checked)}/></div><small>默认关闭，只有你确认后才会启用。</small></div>}
  </div></Modal>;
}
